// 1. Force pull from Trigger to avoid data loss from intermediate nodes (like CONFIG)
let triggerData;
try {
  triggerData = $('🚀 Trigger').first().json;
} catch (e) {
  triggerData = $input.first().json;
}

const body = triggerData.body || triggerData;

// 2. Noise Detection (Resend IDs, Webhook events)
const isResendNoise = (obj) => {
  if (obj.id && String(obj.id).startsWith('re_')) return true;
  if (obj.type && String(obj.type).startsWith('email.')) return true;
  return false;
};

if (isResendNoise(body)) {
  console.log("Ignored: Resend ID or Tracking Event.");
  return []; 
}

// 3. Deep Search for site_web/nom
const findValue = (obj, targetKey) => {
  if (!obj || typeof obj !== 'object') return null;
  const keys = Object.keys(obj);
  const foundKey = keys.find(k => k.toLowerCase() === targetKey.toLowerCase());
  if (foundKey) return obj[foundKey];
  for (const key of keys) {
    if (typeof obj[key] === 'object') {
      const res = findValue(obj[key], targetKey);
      if (res) return res;
    }
  }
  return null;
};

const raw_nom = findValue(body, "nom") || findValue(body, "name");
const raw_site = findValue(body, "site_web") || findValue(body, "url") || findValue(body, "website");
const raw_secteur = findValue(body, "secteur") || findValue(body, "industry") || findValue(body, "category");
const raw_ville = findValue(body, "ville") || findValue(body, "city") || findValue(body, "location");

if (!raw_site) {
  console.log("No site_web found in trigger payload:", JSON.stringify(body));
  return []; 
}

let url = String(raw_site).trim();
if (!url.startsWith("http")) url = "https://" + url;
url = url.replace(/\/$/, "");

let nom = raw_nom ? String(raw_nom).trim() : "";
if (!nom) {
  try { nom = new URL(url).hostname.split('.')[0]; } catch(e) { nom = "Prospect Inconnu"; }
}

return [{ json: { 
  nom,
  site_web: url,
  secteur: (raw_secteur || "autre").toLowerCase().trim(),
  ville: (raw_ville || "France").trim(),
  email: findValue(body, "email") || null,
  pipeline_id: triggerData.pipeline_id || ("gn_"+Date.now()+"_"+Math.random().toString(36).substr(2,6)),
  started_at: new Date().toISOString(),
  retry_state: { stratege: 0, architecte: 0, copywriter: 0, max: 2 }
} }];

const prospect = $("✅ Init").first().json;
const scan = $input.first().json;
const BLACKLIST = ["facebook.com","amazon.","google.com","apple.com","microsoft.com","booking.com","tripadvisor"];
if (!scan.status || scan.status >= 400) return [{ json: { brain_go: false, brain_reason: "Site inaccessible HTTP "+scan.status, prospect, scan } }];
if (!scan.ttfb || scan.ttfb > 9000) return [{ json: { brain_go: false, brain_reason: "TTFB mort ou absent", prospect, scan } }];
try { const host = new URL(prospect.site_web).hostname; if (BLACKLIST.some(b => host.includes(b))) return [{ json: { brain_go: false, brain_reason: "Blackliste", prospect, scan } }]; } catch(e) {}
const brain_context = JSON.stringify({ prospect: { nom: prospect.nom, site: prospect.site_web, secteur: prospect.secteur, ville: prospect.ville }, signals: { ttfb_ms: scan.ttfb, http_status: scan.status, title: scan.title || "ABSENT", h1: scan.h1 || "ABSENT", meta_desc: scan.meta_desc ? "presente ("+scan.meta_desc.length+" chars)" : "ABSENTE" } });
return [{ json: { brain_go: true, brain_context, prospect, scan, retry_state: prospect.retry_state } }];

const raw = $input.first().json;
const text = raw?.content?.find(c=>c.type==="text")?.text || "{}";
const clean = text.replace(/```json\n?/g,"").replace(/```/g,"").trim();
let parsed;
try { parsed = JSON.parse(clean); } catch(e) { parsed = { decision:"GO", confidence:50, top_angles:["Performance","SEO Local"], probleme_critique:"Site non optimise", ton_optimal:"consultant_expert", brain_reasoning:"Fallback", priorite:"moyenne", seuil_qualite_minimum:65, agent_instructions:{stratege:"Focus ROI",architecte:"Mobile-first",copywriter:"Direct"} }; }
return [{ json: { brain_decision_1: parsed, brain_go: parsed.decision==="GO", prospect: $("🧠 Brain Pré-analyse").first().json.prospect, scan: $("🧠 Brain Pré-analyse").first().json.scan, retry_state: $("✅ Init").first().json.retry_state } }];

const all = $input.all();
const scan = all.find(i => i.json.full_text || i.json.design_tokens)?.json || {};
const lh = all.find(i => i.json.performanceScore !== undefined)?.json || {};
return [{ json: { scan_full: scan, lighthouse: lh } }];

